    private fun pick(table: Map<String, Array<IntArray>>, keys: List<String>, family: String, key: String, level: Int): Int? =
        keys.indexOf(key).takeIf { it >= 0 }?.let { table[family]?.get(it)?.get((level - 1).coerceIn(0, LEVELS - 1)) }

    fun base(family: String, metal: String, level: Int): Int? = pick(bases, metals, family, metal, level)
    fun effect(family: String, element: String, level: Int): Int? = pick(effects, elements, family, element, level)
    fun charm(family: String, catalyst: String, level: Int): Int? = pick(charms, catalysts, family, catalyst, level)
}
